schema.content:
Table "Document_Types" {
  "document_type_code" TEXT [pk]
  "document_description" TEXT [not null]
}

Table "Documents" {
  "document_id" INTEGER [pk]
  "document_type_code" TEXT
  "grant_id" INTEGER [not null]
  "sent_date" TIMESTAMP [not null]
  "response_received_date" TIMESTAMP [not null]
  "other_details" TEXT [not null]
}

Table "Grants" {
  "grant_id" INTEGER [pk]
  "organisation_id" INTEGER [not null]
  "grant_amount" TEXT [not null]
  "grant_start_date" TIMESTAMP [not null]
  "grant_end_date" TIMESTAMP [not null]
  "other_details" TEXT [not null]
}

Table "Organisation_Types" {
  "organisation_type" TEXT [pk]
  "organisation_type_description" TEXT [not null]
}

Table "Organisations" {
  "organisation_id" INTEGER [pk]
  "organisation_type" TEXT [not null]
  "organisation_details" TEXT [not null]
}

Table "Project_Outcomes" {
  "project_id" INTEGER [not null]
  "outcome_code" TEXT [not null]
  "outcome_details" TEXT
}

Table "Project_Staff" {
  "staff_id" REAL [pk]
  "project_id" INTEGER [not null]
  "role_code" TEXT [not null]
  "date_from" TIMESTAMP
  "date_to" TIMESTAMP
  "other_details" TEXT
}

Table "Projects" {
  "project_id" INTEGER [pk]
  "organisation_id" INTEGER [not null]
  "project_details" TEXT [not null]
}

Table "Research_Outcomes" {
  "outcome_code" TEXT [pk]
  "outcome_description" TEXT [not null]
}

Table "Research_Staff" {
  "staff_id" INTEGER [pk]
  "employer_organisation_id" INTEGER [not null]
  "staff_details" TEXT [not null]
}

Table "Staff_Roles" {
  "role_code" TEXT [pk]
  "role_description" TEXT [not null]
}

Table "Tasks" {
  "task_id" INTEGER [pk]
  "project_id" INTEGER [not null]
  "task_details" TEXT [not null]
  "eg Agree Objectives" TEXT
}



Ref: "Documents"."grant_id" > "Grants"."grant_id"

Ref: "Documents"."document_type_code" > "Document_Types"."document_type_code"

Ref: "Grants"."organisation_id" > "Organisations"."organisation_id"

Ref: "Organisations"."organisation_type" > "Organisation_Types"."organisation_type"

Ref: "Project_Outcomes"."outcome_code" > "Research_Outcomes"."outcome_code"

Ref: "Project_Outcomes"."project_id" > "Projects"."project_id"

Ref: "Project_Staff"."role_code" > "Staff_Roles"."role_code"

Ref: "Project_Staff"."project_id" > "Projects"."project_id"

Ref: "Projects"."organisation_id" > "Organisations"."organisation_id"

Ref: "Research_Staff"."employer_organisation_id" > "Organisations"."organisation_id"

Ref: "Tasks"."project_id" > "Projects"."project_id"
